def veh(dm):
    if dm is None:
        return 0
    if dm <= 30:
        return 1200
    if dm <= 55:
        return 2600
    if dm <= 80:
        return 4800
    extra = 0
    while 80 + 10 * extra < dm:
        extra += 1
    return 4800 + 900 * extra


def half_up(x):
    return int((Fraction(x) * 2 + 1) // 2)


