    hits = []
    for p, text in text_files():
        if p in allow:
            continue
        for n in needles:
            if n in text:
                hits.append(p)
                break
    return hits


def note_has(path, all_of=(), any_of=(), min_questions=0):
    """A BLOCKED.md / QUESTIONS.md style note: exists, names every item of all_of, one item of each group of any_of."""
    text = read(path)
